{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table maplemonk.tekkitake_amazon_settlement_p_and_l as select o.order_id, coalesce(o.sku,a.sku) as sku, date(order_timestamp) as order_date, cogs.BRAND, cogs.Title, cogs.Category, cogs.Device, sum(ifnull(a.quantity,0)) as Order_Quantity, sum(ifnull(cogs.COGS,0)) as cogs, sum(distinct case when lower(event_type) like any (\'%reimburse%\',\'%refund%\') then ifnull(o.quantity,0) else 0 end) Returned_quantity, sum(case when lower(event_type) like \'%order%\' then Principal_Taxable_value else 0 end) + sum(case when lower(event_type) like \'%order%\' then Product_Tax else 0 end) + sum(case when lower(event_type) like \'%order%\' then COD else 0 end) + sum(case when lower(event_type) like \'%cancel%\' then Shipping else 0 end) + sum(case when lower(event_type) like \'%cancel%\' then Promo_rebates else 0 end) as Overall_Sales, abs(sum(case when lower(event_type) like \'%cancel%\' then Principal_Taxable_value else 0 end) + sum(case when lower(event_type) like \'%cancel%\' then Product_Tax else 0 end) + sum(case when lower(event_type) like \'%cancel%\' then COD else 0 end) + sum(case when lower(event_type) like \'%cancel%\' then Shipping else 0 end) + sum(case when lower(event_type) like \'%cancel%\' then Promo_rebates else 0 end)) as Gross_Sales, abs(sum(case when lower(event_type) like any (\'%reimburse%\',\'%refund%\') then Principal_Taxable_value else 0 end) + sum(case when lower(event_type) like any (\'%reimburse%\',\'%refund%\') then Product_Tax else 0 end) + sum(case when lower(event_type) like any (\'%reimburse%\',\'%refund%\') then COD else 0 end) + sum(case when lower(event_type) like any (\'%reimburse%\',\'%refund%\')then Shipping else 0 end) + sum(case when lower(event_type) like any (\'%reimburse%\',\'%refund%\')then Promo_rebates else 0 end)) as Refunded_Sales, abs(sum(ifnull(Commission,0))) as Commission, abs(sum(ifnull(FBA_Inventory_Reimbursement,0)) + sum(ifnull(FBA_Pick_Pack_Fee,0)) + sum(ifnull(FBA_Weight_Handling_Fee,0)) + sum(ifnull(Fixed_closing_fee,0))) as FBA_Inventory_Fee, sum(ifnull(FBAInboundTransportationFee,0)) as FBA_Storage_Fee, abs(sum(ifnull(TDS_Collected,0))) TDS, abs(sum(ifnull(TCS_Collected,0))) TCS, sum(ifnull(Cost_of_Advertising,0)) as Marketing_Spend from maplemonk.amazon_order_level_transaction_fact_items o left join maplemonk.tekkitake_amazon_fact_items a on o.order_id = a.order_id and o.sku = a.sku left join ( select SKU sku_code, FSN, ASIN, BRAND, Title, Category, Device, cast(PARSE_DATE(\'%m/%d/%Y\', start_date) as date) as start_date, cast(PARSE_DATE(\'%m/%d/%Y\', END_DATE) as date) as END_DATE, cast(landing_cost as float64) as COGS, PP_Fee_Size_Band, WH_Fee_Size_Band, safe_cast(Selling_price as float64) as Selling_Price_SP from `MAPLEMONK.GS_SKU_MASTER` qualify row_number() over(partition by SKU , start_date ,END_DATE order by 1) = 1 )cogs on lower(coalesce(o.sku,a.sku)) = lower(trim(cogs.SKU_code)) and date(a.order_timestamp) >= cogs.start_date and date(a.order_timestamp) <= cogs.END_DATE group by 1,2,3,4,5,6,7 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            